# 파일시스템 기억: 기억 하나 = 파일 하나, 도구는 ls/grep 과 같은 일
import tempfile, pathlib
root = pathlib.Path(tempfile.mkdtemp())
files = {
    "procedural/AGENTS.md": "실험 실행: ./launch.sh --gpus 4 (지난주에 정함)",
    "semantic/user.md": "이메일은 지우기 전에 반드시 물어본다\n돈이 드는 실험은 먼저 확인",
    "episodic/2026-10-12.json": '{"turns": ["launch.sh 가 OOM 으로 실패", "--gpus 4 로 해결"]}',
}
for rel, text in files.items():
    p = root / rel; p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(text, encoding="utf-8")

def ls(d=""):
    return sorted(p.relative_to(root).as_posix() for p in (root / d).rglob("*") if p.is_file())
def grep(word):
    return [(p.relative_to(root).as_posix(), line) for p in root.rglob("*") if p.is_file()
            for line in p.read_text(encoding="utf-8").splitlines() if word in line]

print(ls())
print(grep("launch"))

# Mem0식 갱신: 새 사실마다 ADD / UPDATE / DELETE / NOOP 중 하나. 판정 LLM 은 규칙 스텁
memory = {"food": "이탈리아 음식을 좋아한다", "pet": "강아지를 키운다"}

def stub_decide(key, fact):            # 진짜는 LLM 이 기존 기억과 새 사실을 읽고 고른다
    if fact is None:
        return "DELETE" if key in memory else "NOOP"
    if key not in memory:
        return "ADD"
    return "NOOP" if memory[key] == fact else "UPDATE"

def apply(key, fact):
    op = stub_decide(key, fact)
    if op in ("ADD", "UPDATE"):
        memory[key] = fact
    elif op == "DELETE":
        memory.pop(key)
    print(f"{op:6} {key}: {fact}")

apply("allergy", "글루텐 알레르기가 있다")
apply("food", "지중해식, 특히 구운 해산물을 찾는다")
apply("pet", "강아지를 키운다")
apply("pet", None)                      # "강아지를 입양 보냈어"
print(memory)

# 기억 벤치마크의 두 지표: 근거 recall@k 와 답의 토큰 F1 (LoCoMo 식)
from collections import Counter
def recall_at_k(ranked_ids, gold_ids, k):
    return len(set(ranked_ids[:k]) & set(gold_ids)) / len(gold_ids)

def f1(pred, gold):
    p, g = pred.lower().split(), gold.lower().split()
    same = sum((Counter(p) & Counter(g)).values())
    if same == 0:
        return 0.0
    prec, rec = same / len(p), same / len(g)
    return 2 * prec * rec / (prec + rec)

ranked = ["s7", "s2", "s9", "s4", "s1"]          # 검색기가 낸 순서
gold = ["s4", "s7"]                               # 답의 근거가 된 대화 조각
for k in (1, 3, 5):
    print(f"recall@{k} = {recall_at_k(ranked, gold, k):.2f}")
print("F1 =", round(f1("her daughter birthday party", "daughter"), 2))
print("F1 =", round(f1("daughter", "daughter"), 2))
